package nl.voetbalhub.app;
import android.app.Activity;import android.graphics.Bitmap;import org.json.*;import java.util.*;import java.io.InputStream;
/** Scoped local artwork and per-feed byte/asset/perceptual collision checks. */
public final class ImageRegistry39 {
 private static JSONArray registry;
 public static synchronized void load(Activity a){if(registry!=null)return;try(InputStream in=a.getAssets().open("image-registry39.json")){registry=new JSONObject(new String(BoundedInput.read(in,200000),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("records");}catch(Exception ignored){registry=new JSONArray();}}
 public static void apply(JSONObject article){if(registry==null)return;try{StringBuilder text=new StringBuilder(article.optString("headline")).append('\n').append(article.optString("standfirst"));JSONArray body=article.optJSONArray("body");if(body==null)return;for(int i=0;i<body.length();i++)text.append('\n').append(body.getString(i));byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(text.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder hash=new StringBuilder();for(byte b:bytes)hash.append(String.format(Locale.ROOT,"%02x",b&255));for(int i=0;i<registry.length();i++){JSONObject r=registry.getJSONObject(i);if(!r.getString("articleId").equals(article.optString("id"))||!r.getString("contentHash").equals(hash.toString()))continue;article.put("imageAsset",r.getString("asset")).put("imageAssetId",r.getString("assetId")).put("imageRights","cleared").put("imageCredit",r.getString("credit")).put("imageCaption",r.getString("caption")).put("imageSource","https://github.com/sanderbrink-spec/Voetbalhub/tree/work/veldio-interface-39/android-ui/assets/news-photos").put("imageLicenseUrl","").put("imageReview",new JSONObject().put("method","own-editorial-vector39").put("contextOnly",true).put("assetSha256",r.getString("sha256")).put("dHash",r.getString("dHash")));return;}}catch(Exception ignored){}}
 public static int distance(String a,String b){try{if(!a.matches("[0-9a-fA-F]{16}")||!b.matches("[0-9a-fA-F]{16}"))return 65;return Long.bitCount(Long.parseUnsignedLong(a,16)^Long.parseUnsignedLong(b,16));}catch(Exception ignored){return 65;}}
 public static String dHash(Bitmap bitmap){Bitmap small=Bitmap.createScaledBitmap(bitmap,9,8,true);long bits=0;for(int y=0;y<8;y++)for(int x=0;x<8;x++){int l=small.getPixel(x,y),r=small.getPixel(x+1,y);int lv=android.graphics.Color.red(l)*299+android.graphics.Color.green(l)*587+android.graphics.Color.blue(l)*114,rv=android.graphics.Color.red(r)*299+android.graphics.Color.green(r)*587+android.graphics.Color.blue(r)*114;bits=(bits<<1)|(lv>rv?1:0);}if(small!=bitmap)small.recycle();return String.format(Locale.ROOT,"%016x",bits);}
 public static final class Session {
  private final Set<String> assets=new HashSet<>(),hashes=new HashSet<>();private final ArrayList<String> perceptual=new ArrayList<>(),decoded=new ArrayList<>();
  public synchronized boolean claim(JSONObject a){JSONObject r=a.optJSONObject("imageReview");String id=a.optString("imageAssetId",a.optString("imageAsset",a.optString("imageUrl"))),h=r==null?"":r.optString("assetSha256"),p=r==null?"":r.optString("dHash");if(id.isEmpty())return false;if(assets.contains(id)||!h.isEmpty()&&hashes.contains(h))return false;if(!p.isEmpty())for(String previous:perceptual)if(distance(p,previous)<=6)return false;assets.add(id);if(!h.isEmpty())hashes.add(h);if(!p.isEmpty())perceptual.add(p);return true;}
  public synchronized boolean decoded(Bitmap b){String h=dHash(b);for(String old:decoded)if(distance(h,old)<=6)return false;decoded.add(h);return true;}
 }
}
